// Topic-specific query, debugging, and design reviews. Evaluation scenarios are
// manual acceptance checks; the Practice workspace does not execute database code.
const review = (topic, difficulty, slug, title, prompt, objective, requirements, cases, hints, solution, followUp) => ({
    id: `backend-db-${slug}-v1`, career: "Backend Developer", phase: "Databases", topic, title, difficulty,
    kind: "written", language: "Database technical response",
    estimatedTime: difficulty === "Easy" ? "20–30 minutes" : difficulty === "Medium" ? "35–50 minutes" : "50–75 minutes",
    problemStatement: prompt, simplerProblem: objective,
    learningObjectives: [objective, `Evaluate the ${topic} result against the supplied boundary case.`],
    prerequisites: ["Backend data types, asynchronous calls, and resource ownership"], conceptsToReview: [topic],
    requirements, examples: cases.map(([input, output]) => ({input, output, explanation: objective})),
    tests: cases.map(([input, expected], i) => ({name:`Acceptance scenario ${i+1}`,input,expected})),
    hints, approach: `${hints[0]} ${hints[1]} Check the stated data and concurrency assumptions before evaluating the result.`,
    walkthrough: cases.map(([input,output]) => `${input} → ${output}`).join("\n"),
    solutionCode: solution, solutionLines: solution.split("\n").filter(Boolean),
    completionCriteria: requirements, commonMistakes: [],
    starterCode: "Query or design:\n\nExpected results and boundary checks:\n\nAssumptions and limitations:\n", followUp
});

